package com.friendspharma.app.dto.request;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import lombok.Data;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * Purchase invoice create/update payload.
 *
 * <p>Deliberately absent, because the server owns them:
 * <ul>
 *   <li>{@code invoiceNo} and {@code batchNo} — generated by DocumentNumberService</li>
 *   <li>{@code orgId}, {@code companyId}, {@code branchId} — taken from the JWT session</li>
 *   <li>every line's {@code totalPrice}, and the invoice {@code totalAmount},
 *       {@code invoiceDisAmt}, {@code totalDiscount}, {@code amountToBePaid} —
 *       calculated by PurchaseCalculator</li>
 *   <li>{@code mnpPrice}, {@code mrpPrice}, {@code igta}, {@code noOfPcs} —
 *       snapshotted from the selected product</li>
 * </ul>
 * Leaving them off the DTO entirely means Jackson has nowhere to bind a forged
 * value, so no future edit can start trusting one by accident.
 */
@Data
public class PurchaseRequest {

    @NotNull(message = "Supplier is required.")
    private Long supplierId;

    /**
     * Optional. Defaults to the branch on the session; supplying one lets a
     * multi-branch user purchase into a branch other than their default.
     */
    private Long branchId;

    /** Defaults to today when omitted. Cannot be in the future. */
    @PastOrPresent(message = "Purchase date cannot be in the future.")
    private LocalDate transactionDate;

    @Size(max = 50, message = "Challan number must not exceed 50 characters.")
    private String challanNo;

    @NotBlank(message = "Costing basis is required.")
    @Pattern(regexp = "^(MNP|MRP)$", message = "Costing basis must be MNP or MRP.")
    private String purchaseType;

    @Pattern(regexp = "^(PHARMA|NON-PHARMA)$", message = "Product type must be PHARMA or NON-PHARMA.")
    private String productType;

    @Size(max = 20, message = "Payment type must not exceed 20 characters.")
    private String paymentType;

    @DecimalMin(value = "0.0", message = "Invoice discount % must be zero or more.")
    @DecimalMax(value = "100.0", message = "Invoice discount % cannot exceed 100.")
    private BigDecimal invoiceDisPct;

    @DecimalMin(value = "0.0", message = "Tax must be zero or more.")
    private BigDecimal totalTax;

    @DecimalMin(value = "0.0", message = "Service charge must be zero or more.")
    private BigDecimal serviceCharge;

    /**
     * [V68] Supplier cashback on this invoice. Reduces what is owed and what the
     * goods cost. Not for a rebate received later — that is a supplier credit.
     */
    @DecimalMin(value = "0.0", message = "Cashback must be zero or more.")
    private BigDecimal cashbackAmount;

    @DecimalMin(value = "0.0", message = "Given amount must be zero or more.")
    private BigDecimal givenAmount;

    /**
     * Pay the invoice discount along with the bill.
     *
     * <p>The trade practice: on a discounted invoice the gross is handed over
     * and the supplier returns the discount later. Setting this takes the
     * advance from the invoice's own discount figure, so what is booked as
     * recoverable is the invoice, not a number retyped at the counter.
     */
    private Boolean payInvoiceDiscount;

    /**
     * The part of {@code givenAmount} that settles no part of this bill.
     *
     * <p>Set directly for an advance paid for some other reason, or leave null
     * and let {@code payInvoiceDiscount} derive it. Handing over more than the
     * bill is only accepted when the excess is declared one of these two ways.
     */
    private BigDecimal advanceAmount;

    @Size(max = 100, message = "Remarks must not exceed 100 characters.")
    private String remarks;

    /**
     * DRAFT (D), PENDING (P) or APPROVED (A). Defaults to PENDING.
     * A draft skips stock movement; approval is what commits it.
     */
    @Pattern(regexp = "^(D|P|A|DRAFT|PENDING|APPROVED)$",
             message = "Status must be DRAFT, PENDING or APPROVED.")
    private String status;

    @NotEmpty(message = "Add at least one product line.")
    @Size(max = 500, message = "A purchase invoice is limited to 500 lines.")
    @Valid
    private List<PurchaseLine> lines;

    /** One purchase detail line. */
    @Data
    public static class PurchaseLine {

        @NotNull(message = "Product is required.")
        private Long productId;

        /* [V69] Deliberately not @NotNull. A GIFT line has no purchase quantity
           at all — the form leaves the box empty and sends null — and a bean
           annotation cannot see LINE_KIND, so it refused the one shape it was
           meant to allow. Presence is checked per kind in
           PurchaseServiceImpl.requireLineShape, where the kind is known and the
           refusal can say something useful: an empty quantity on an ordinary
           line is answered with "mark the line as a gift" rather than
           "Quantity is required." */
        @DecimalMin(value = "0.0", message = "Quantity cannot be negative.")
        @Digits(integer = 10, fraction = 4, message = "Quantity may have at most 10 digits and 4 decimals.")
        private BigDecimal quantity;

        /**
         * [V67] Free units the supplier gave with this line — "buy 10, get 12".
         *
         * <p>Zero or absent on an ordinary line. It adds to stock and lowers the
         * cost per piece; it never adds to a money total, so no price, discount
         * or invoice figure reads it.
         */
        @DecimalMin(value = "0.0", message = "Bonus quantity cannot be negative.")
        @Digits(integer = 10, fraction = 4, message = "Bonus may have at most 10 digits and 4 decimals.")
        private BigDecimal bonusQty;

        /**
         * [V69] PURCHASE (the default) or GIFT — a different product given free.
         * A GIFT line carries no quantity and no money, only a bonus.
         */
        private String lineKind;

        @DecimalMin(value = "0.0", message = "Discount % must be zero or more.")
        @DecimalMax(value = "100.0", message = "Discount % cannot exceed 100.")
        private BigDecimal discountPct;

        @DecimalMin(value = "0.0", message = "Flat discount must be zero or more.")
        private BigDecimal flatDiscount;

        @DecimalMin(value = "0.0", message = "TP % must be zero or more.")
        @DecimalMax(value = "100.0", message = "TP % cannot exceed 100.")
        private BigDecimal tpPct;

        /*
         * batchNo and expiryDate are deliberately absent.
         *
         * The line's batch is derived from the invoice's generated BATCH_NO, and
         * the expiry is always today + 365 days. Both are server-owned, so — as
         * with the money fields — there is no property here for a client to bind
         * a value to.
         */

        @NotBlank(message = "Sales type is required.")
        @Pattern(regexp = "^(BOX|STRIP|PCS)$", message = "Sales type must be BOX, STRIP or PCS.")
        private String salesType;
    }
}
